def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, cells))

    candidates = []
    for idx, (color, cells) in enumerate(comps):
        for r0, c0 in cells:
            for vd in (-1, 1):
                for hd in (-1, 1):
                    # A candidate is a one-cell-wide L with this elbow.
                    vrun = []
                    r = r0
                    while (r, c0) in cells:
                        vrun.append((r, c0))
                        r += vd
                    hrun = []
                    c = c0
                    while (r0, c) in cells:
                        hrun.append((r0, c))
                        c += hd
                    if len(vrun) < 2 or len(hrun) < 2:
                        continue
                    if set(vrun) | set(hrun) != cells:
                        continue

                    # Look outward from the elbow, opposite the two arms,
                    # for the nearest other colored component.
                    for axis in (0, 1):
                        best = None
                        for j, (other_color, other_cells) in enumerate(comps):
                            if j == idx:
                                continue
                            for rr, cc in other_cells:
                                if axis == 0:
                                    d = (rr - r0) * (-vd)
                                    off = abs(cc - c0)
                                else:
                                    d = (cc - c0) * (-hd)
                                    off = abs(rr - r0)
                                if d > 0 and off <= 1:
                                    score = (d, off)
                                    if best is None or score < best[0]:
                                        best = (score, j)
                        if best is not None:
                            candidates.append((best[0], -(len(cells)), idx, best[1]))

    if not candidates:
        return [row[:] for row in grid]

    _, _, marker_idx, target_idx = min(candidates)
    marker_color = comps[marker_idx][0]
    target_cells = comps[target_idx][1]
    out = [row[:] for row in grid]
    for r, c in target_cells:
        out[r][c] = marker_color
    return out
